python3 -c "
from labpy import *
import numpy as np, itertools
rows=load()
ids=['C-114','C-127','C-203','C-241','C-318','C-352']
cost=dict(zip(ids,[3,4,4,3,5,5]))
T=['R1','R2','R3','R4','R5']
rep={}; can={}
for r in rows:
    if r['op']=='replay': rep.setdefault((r['args']['trace'],tuple(r['args']['opts'])),[]).extend(r['result']['per_rep_ms'])
    else: can.setdefault(tuple(r['args']['opts']),[]).extend(r['result']['per_rep_ms'])
w=np.array([0.2526,0.088,0.2847,0.0633,0.2978])
base=np.array([np.mean(rep[(t,())]) for t in T])
ratio={i:np.array([np.mean(rep[(t,(i,))]) for t in T])/base for i in ids}
feas=[]
for k in range(1,7):
    for s in itertools.combinations(ids,k):
        if sum(cost[i] for i in s)<=11:
            r=np.ones(5)
            for i in s: r*=ratio[i]
            lat=(base*r)@w
            feas.append((base@w/lat,s))
feas.sort(reverse=True)
print(len(feas))
for f in feas: print(round(f[0],4),f[1])
"
